import{_ as t}from"./chunks/EditPublishedElement.DbyKNdto.js";import{_ as i,c as o,a2 as a,o as s}from"./chunks/framework.BQmytedh.js";const n="/assets/CreatePublishSelection1.Clg5fNg3.png",l="/assets/CreatePublishForm.BbdKW6I3.png",r="/assets/CreatePublishFormManuscript.Dukgye7E.png",c="/assets/CreatePublishResume.BZN_cAU3.png",h="/assets/CreatePublishResumeEmbargo.fZhos0ST.png",p="/assets/EditCollection.BIYmJhFd.png",u="/assets/EditCollection2.DE5tWkqF.png",d="/assets/CreatePublishHandle.CNgz4JhC.png",m="/assets/BrowsePublishedElementsDetail.tX20AYyD.png",b="/assets/BrowsePublishedElementsDetailItem.AGJsgfA0.png",_=JSON.parse('{"title":"Publish a dataset into Browse","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/publishing-calculations/publish-process.md","filePath":"doc/guides/usage/publishing-calculations/publish-process.md"}'),g={name:"doc/guides/usage/publishing-calculations/publish-process.md"};function f(w,e,y,k,P,v){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="publish-a-dataset-into-browse" tabindex="-1">Publish a dataset into Browse <a class="header-anchor" href="#publish-a-dataset-into-browse" aria-label="Permalink to &quot;Publish a dataset into Browse&quot;">​</a></h1><p>Calculations uploaded into the Create module are only accessible to registered ioChem-BD users, this will usually be comprised of a small group of individuals that conform the research group/center. Their calculations will not be accessible until they are published in the <strong>Browse module</strong>, the public module of <strong>ioChem-BD</strong>.</p><p>Before moving to the publication mechanism, it is interesting to read again the section about the organizational elements that conform each module: <a href="/doc/what-is-iochem-bd.html#modular-architecture">ioChem-BD organizative elements</a>.</p><p>So published projects become Collections and published calculations become items on the Browse module, it is a mere grammatical change to align with <a href="https://duraspace.org/dspace/" target="_blank" rel="noreferrer">DSpace software</a> naming convention.</p><p>Once published, both elements are linkable, searchable and viewable publicly.</p><h2 id="publication-requirements" tabindex="-1">Publication requirements <a class="header-anchor" href="#publication-requirements" aria-label="Permalink to &quot;Publication requirements&quot;">​</a></h2><p>To perform calculation publication, users must have defined (on Browse module) a <strong>community where to publish</strong>. The steps required to create a community and assign its administrator falls upon ioChem-BD&#39;s system administator and are described on <a href="./../../installation/publishing-endpoints-definition.html">publishing endpoints definition</a> page.</p><h2 id="publication-steps" tabindex="-1">Publication steps <a class="header-anchor" href="#publication-steps" aria-label="Permalink to &quot;Publication steps&quot;">​</a></h2><h3 id="select-the-elements-to-publish" tabindex="-1">Select the elements to publish <a class="header-anchor" href="#select-the-elements-to-publish" aria-label="Permalink to &quot;Select the elements to publish&quot;">​</a></h3><p>On Create module, navigate to the project where the desired calculations reside.</p><p>Then you must select it and right click it, then choose <em>Publish</em> from the <em>Browse module</em> section of the context menu.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Since ioChem-BD v3.0, you can only select and publish the entire project, not part of its content. You must select the project <strong>only</strong> prior publishing. If you select other content, the publish option will not be available.</p></div><p><img src="'+n+'" alt="Project selection"></p><p>If an error message appears at this point, please read the FAQ entry about <a href="/doc/faqs/general/create-publish-error.html">no publishing community defined</a>.</p><h3 id="publication-form" tabindex="-1">Publication form <a class="header-anchor" href="#publication-form" aria-label="Permalink to &quot;Publication form&quot;">​</a></h3><p>After selecting the project and clicking &quot;Publish&quot;, a streamlined publication form will appear. This form consolidates all publication settings into a single, easy-to-navigate interface.</p><p><img src="'+l+'" alt="Publication form"></p><p>At the top of the form, you&#39;ll see a summary showing the project name and the number of calculations to be published. You must first select the <strong>destination community</strong> from the dropdown menu before the form fields become active.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you have multiple communities available, select the appropriate one where you want your dataset to appear.</p></div><p>The publication form is organized into four numbered sections:</p><h4 id="section-1-dataset-type" tabindex="-1">Section 1: Dataset Type <a class="header-anchor" href="#section-1-dataset-type" aria-label="Permalink to &quot;Section 1: Dataset Type&quot;">​</a></h4><p>This section allows you to specify whether your dataset is independent or linked to a published manuscript.</p><ul><li><strong>Independent Dataset</strong>: Select this option if your data is standalone and not associated with any publication.</li><li><strong>Linked to Manuscript</strong>: Select this option if your dataset is supplementary material for a published paper.</li></ul><p>When &quot;Linked to Manuscript&quot; is selected, additional fields appear:</p><p><img src="'+r+'" alt="Manuscript information"></p><blockquote><ul><li><strong>DOI (Digital Object Identifier)</strong>: Enter the DOI of the related manuscript (e.g., <code>10.1021/acscatal.xxxxxx</code>)</li><li><strong>Article Title</strong>: Enter the title of the related paper</li><li><strong>Journal</strong>: Type to search and select the journal name</li></ul></blockquote><p>If the manuscript is not yet published, check the <strong>&quot;Manuscript is a pre-print (not yet published)&quot;</strong> checkbox. You can provide the paper information later once it is published.</p><h4 id="section-2-authors-affiliations" tabindex="-1">Section 2: Authors &amp; Affiliations <a class="header-anchor" href="#section-2-authors-affiliations" aria-label="Permalink to &quot;Section 2: Authors &amp; Affiliations&quot;">​</a></h4><p>This section allows you to add authors and their institutional affiliations to your dataset.</p><p><strong>Adding Authors:</strong></p><ol><li>Type in the author search box to find existing platform users</li><li>Click the <strong>Add</strong> button to add the selected author</li><li>Authors appear as chips that can be removed by clicking the × icon</li></ol><p><strong>Adding Institutions:</strong></p><ol><li>Type the institution name in the text field</li><li>Click the <strong>Add</strong> button to add the institution</li><li>Institutions appear as chips below the input field</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The current user is automatically added as the first author. You can add external contributor names but only if they follow the format: <strong>Surname, Name</strong>, using a comma and a whitespace to separate both elements.</p></div><h4 id="section-3-discovery" tabindex="-1">Section 3: Discovery <a class="header-anchor" href="#section-3-discovery" aria-label="Permalink to &quot;Section 3: Discovery&quot;">​</a></h4><p>This section helps make your dataset more discoverable through keywords.</p><ol><li>Type a keyword in the search box (you can search existing terms or add new ones)</li><li>Click the <strong>Add</strong> button to add the keyword</li><li>Keywords appear as chips that can be removed by clicking the × icon</li></ol><p>Adding relevant chemical and scientific terms will help other researchers find your published data through Browse module searches.</p><h4 id="section-4-publication-options" tabindex="-1">Section 4: Publication Options <a class="header-anchor" href="#section-4-publication-options" aria-label="Permalink to &quot;Section 4: Publication Options&quot;">​</a></h4><p>This section provides additional options for your publication:</p><blockquote><ul><li><strong>Request a DOI for published project</strong>: When checked, a DOI (Digital Object Identifier) will be requested for your published collection. Once assigned, you will receive an email notification with the DOI.</li><li><strong>Embargo published elements</strong>: When checked, access to your published content will be restricted to reviewers only until you lift the embargo.</li></ul></blockquote><div class="info custom-block"><p class="custom-block-title">DOI Generation</p><p>DOI determination can take some minutes to resolve because it requires contacting third party services (CrossRef). Once the DOI has been assigned, you will receive an email with the DOI for the published collection.</p></div><p>You can read more about the embargo feature on the following pages:</p><ul><li><a href="./embargo.html">Setting the embargo</a><ul><li><a href="./embargo.html#accessing-the-embargoed-elements">Accessing the embargoed elements</a></li><li><a href="./embargo.html#lifting-the-embargo">Lifting the embargo</a></li></ul></li></ul><h3 id="publishing-the-data" tabindex="-1">Publishing the data <a class="header-anchor" href="#publishing-the-data" aria-label="Permalink to &quot;Publishing the data&quot;">​</a></h3><p>Once all sections have been filled, click the <strong>Publish Data</strong> button at the bottom of the form. The publication process will begin, and a progress indicator will show the status.</p><h3 id="publication-resume" tabindex="-1">Publication resume <a class="header-anchor" href="#publication-resume" aria-label="Permalink to &quot;Publication resume&quot;">​</a></h3><p>After the publication process completes successfully, a resume window will appear showing the results:</p><p><img src="'+c+'" alt="Publication resume"></p><p>The resume displays:</p><ul><li>A success message with the project name</li><li>Badges showing the number of calculations published and DOI request status</li></ul><p>The resume is organized into three sections:</p><p><strong>View Published Project</strong> : Contains a link to view your newly published collection on the Browse module. Click the <strong>View</strong> button to open the published collection in a new tab.</p><p><strong>Peer Review Access</strong> <em>(only visible if embargo was enabled)</em> : If you enabled the embargo option, this section provides a shareable reviewer link. Click <strong>Copy</strong> to copy the link to your clipboard and share it with reviewers who need access to the embargoed content.</p><p><img src="'+h+'" alt="Publication resume with embargo"></p><p><strong>Project Management</strong> : Contains a link to the collection editor where you can modify properties or lift the embargo. Click <strong>Open Editor</strong> to access the Browse collection management page.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All administrative actions and links shown in the resume can be accessed anytime by clicking on the edit icon placed on the right side of each published collection in the Create module.</p></div><h3 id="published-elements-manipulation" tabindex="-1">Published elements manipulation <a class="header-anchor" href="#published-elements-manipulation" aria-label="Permalink to &quot;Published elements manipulation&quot;">​</a></h3><p>In the navigation frame, published elements will display a green tick on the right side.</p><p>Published projects and subprojects will also have an additional black tick that points to the Browse <em>Collection edit</em> page.</p><p><img src="'+t+'" alt=""></p><p>This page allows to:</p><ul><li>Change published collection name</li><li>Set related article information</li><li><a href="./embargo.html#lifting-the-embargo">Lift embargo</a></li><li>Copy reviewers link</li></ul><p>On the page that shows, the first section allows to change title, subtitle and description of the published collection:</p><p><img src="'+p+'" alt="Published collection edition form"></p><p>The next section allows set publisher metadata and embargo options:</p><p><img src="'+u+'" alt="Edit journal and embargo information section"></p><h3 id="view-published-elements-from-create" tabindex="-1">View published elements from Create <a class="header-anchor" href="#view-published-elements-from-create" aria-label="Permalink to &quot;View published elements from Create&quot;">​</a></h3><p>The projects and calculations published have a handle and a green tick on its right side.</p><p><img src="'+d+'" alt="Publication handle"></p><p>Clicking on the handle link will navigate to the published Browse content. Each collection can hold multiple Items (calculations) inside.</p><p><img src="'+m+'" alt="Published collection items"></p><p>Each published item displays the uploaded input file, an output converted CML file, additional files and its metadata.</p><p><img src="'+b+'" alt="Published item detail"></p>',74)]))}const x=i(g,[["render",f]]);export{_ as __pageData,x as default};
